"""Demo: the two-sided squeeze identity (a, x] U [x, b) = (a, b)."""
from __future__ import annotations


def squeeze_epsilon(a: float, x: float, b: float) -> float:
    """Radius of the Euclidean ball produced by gluing (a, x] and [x, b)."""
    assert a < x < b
    return min(x - a, b - x)


def ball_inside_union(a: float, x: float, b: float, samples: int = 1000) -> bool:
    """Check (x - e, x + e) is inside (a, x] U [x, b) on a fine sample."""
    e = squeeze_epsilon(a, x, b)
    lo, hi = x - e, x + e
    for i in range(1, samples):
        y = lo + (hi - lo) * i / samples
        in_left = a < y <= x
        in_right = x <= y < b
        if not (in_left or in_right):
            return False
    return True


if __name__ == "__main__":
    for a, x, b in [(-2.0, 0.5, 3.0), (0.0, 1.0, 2.0), (-5.0, -1.0, 4.0)]:
        e = squeeze_epsilon(a, x, b)
        ok = ball_inside_union(a, x, b)
        print(f"a={a}, x={x}, b={b}: epsilon={e}, ball inside union: {ok}")

"""Demo: verify the phantom number of R equals two on a battery of tests."""
from __future__ import annotations
from typing import Callable

SetR = Callable[[float], bool]


def lower_open_at(U: SetR, x: float, reach: float = 1.0, steps: int = 1500) -> bool:
    if not U(x):
        return False
    r = reach
    while r > 1e-9:
        b = x + r
        if all(U(x + (b - x) * i / steps) for i in range(steps)):
            return True
        r /= 2.0
    return False


def upper_open_at(U: SetR, x: float, reach: float = 1.0, steps: int = 1500) -> bool:
    if not U(x):
        return False
    r = reach
    while r > 1e-9:
        a = x - r
        if all(U(a + (x - a) * (i + 1) / steps) for i in range(steps)):
            return True
        r /= 2.0
    return False


def consensus_open_at(U: SetR, x: float) -> bool:
    return lower_open_at(U, x) and upper_open_at(U, x)


if __name__ == "__main__":
    tests = {
        "(-1, 2) [euclidean-open]": (lambda t: -1.0 < t < 2.0, [-0.9, 0.0, 1.9]),
        "[0, 1) [lower-open only]": (lambda t: 0.0 <= t < 1.0, [0.0]),
        "(0, 1] [upper-open only]": (lambda t: 0.0 < t <= 1.0, [1.0]),
    }
    for name, (U, pts) in tests.items():
        for x in pts:
            print(f"{name} at {x}: consensus-open = {consensus_open_at(U, x)}")

